const article = document.getElementById('article');
const escapeHtml = (value = '') => { const node = document.createElement('span'); node.textContent = value; return node.innerHTML; };
function format(text = '') { return escapeHtml(text).replace(/^### (.*)$/gm, '<h3>$1</h3>').replace(/^## (.*)$/gm, '<h2>$1</h2>').replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>').replace(/\*(.*?)\*/g, '<em>$1</em>').replace(/\n\n+/g, '</p><p>').replace(/\n/g, '<br>'); }
async function loadArticle() { const slug = location.pathname.split('/').filter(Boolean).pop(); try { const response = await fetch(`/api/cms?action=post&slug=${encodeURIComponent(slug)}`); const data = await response.json(); if (!response.ok) throw new Error(); const post = data.post; document.title = `${post.seoTitle || post.title} | Browlicious`; const description = document.createElement('meta'); description.name = 'description'; description.content = post.seoDescription || post.excerpt; document.head.append(description); article.innerHTML = `<a class="back" href="/blog">← Back to journal</a><p class="eyebrow">${escapeHtml(post.author || 'Browlicious team')}</p><h1>${escapeHtml(post.title)}</h1><p class="article-intro">${escapeHtml(post.excerpt)}</p>${post.coverImage ? `<img class="article-cover" src="${post.coverImage}" alt="${escapeHtml(post.coverAlt || post.title)}">` : ''}<div class="article-content"><p>${format(post.body)}</p></div>`; } catch { article.innerHTML = '<a class="back" href="/blog">← Back to journal</a><h1>Article not found.</h1><p class="article-intro">This article may have been moved or is not published yet.</p>'; } }
loadArticle();
